update tb_stock_request
set status = 'APPROVE',
    process_date = sysdate,
    process_member_id = #{adminId}
where request_no = #{requestNo}
  and status = 'WAIT'

update tb_stock_request
set status = 'REJECT',
    process_date = sysdate,
    process_member_id = #{adminId}
where request_no = #{requestNo}
  and status = 'WAIT'

update tb_stock_request
set status = 'CANCEL',
    process_date = sysdate,
    process_member_id = #{memberId}
where request_no = #{requestNo}
  and status = 'WAIT'
  and member_id = #{memberId}
